var seed = Math.random() * 12421;
var particles = [];
var mySize;
var parNum;
var color_vision;

function setup() {
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
	createCanvas(1920, 1080);
	colorMode(HSB, 255);
	//pixelDensity(3);
	background(255);
	parNum = int(random(8,14));
	for (let j = 0; j < 5; j++) {
		for (let i = 0; i < parNum; i++) {
			particles.push(new Particle( width/2, height/2))
		}
	}
	color_vision = random([1, 2, 3, 4, 5, 6])
}

function draw() {
	for (let i = particles.length - 1; i > 0; i--) {
		if (i < particles.length) {
			if (int(seed) % 2 == 0) {
				particles[i].color_vision = color_vision;
			}
			particles[i].update();
			particles[i].show();
			if (particles[i].alpha2 < 30) {
				particles[i].explode();
			}
			if (particles[i].finished()) {
				particles.splice(i, 1);
				noLoop();
			}
		}
	}
}

let lapse = 0;    // mouse timer
function mousePressed(){
// prevents mouse press from registering twice
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() +
    ".jpg");
    lapse = millis();
  }
}

// === Tab: Particle ===
function Particle(x, y) {

	this.x = x;
	this.y = y;
	this.pos = createVector(this.x, this.y);
	this.vel = createVector(random(1, 5) * random(-1, 1), 0);
	this.acc = createVector(random(2.5, 3.5) * random(-0.025, 0.025), 0 * random(-0.025, 0.025));
	this.alpha1 = int(random(100));
	this.alpha2 = 100;
	this.r = 1.5*random(height / 100) * random(35, 25);
	this.particles2 = [];
	this.color1 = 0;
	this.color2 = 0;
	this.grad = 0;
	this.offset = 1 * random(2.0, 1.0);
	this.color_vision = random([1, 2, 3, 4, 5]);

	this.update = function() {
		if (this.color_vision == 1) {
			this.color1 = color(255, 255, 255, this.alpha1);
			this.color2 = color(0,0,0, this.alpha2);
		}
		if (this.color_vision == 2) {
			this.color1 = color(242, 68, 68, this.alpha1);
			this.color2 = color(167, 217, 217, this.alpha2);
		}
		if (this.color_vision == 3) {
			this.color1 = color(102, 121, 107, this.alpha1);
			this.color2 = color(222, 239, 87, this.alpha2);
		}
		if (this.color_vision == 4) {
			this.color1 = color(242, 170, 82, this.alpha1);
			this.color2 = color(0, 169, 104, this.alpha2);
		}
		if (this.color_vision == 5) {
			this.color1 = color(146, 241, 222, this.alpha1);
			this.color2 = color(166, 116, 88, this.alpha2);
		}
		if (this.color_vision == 6) {
			this.color1 = color(184, 219, 187, this.alpha1);
			this.color2 = color(255, 255, 255, this.alpha2);
		}
		this.vel.add(this.acc);
		this.pos.add(this.vel);
		this.alpha2 -= random(1);
		this.alpha1 += random(1);
		if (this.r > 1) {
			this.r -= 1;
		}
	};

	this.show = function() {
		// noStroke();
		// fill(0);
		noFill();
		strokeWeight(random(1.5));

		//grad
		this.grad = drawingContext.createRadialGradient(this.pos.x + random(-this.offset, this.offset), this.pos.y + random(-this.offset, this.offset), 0,
			this.pos.x + random(-this.offset, this.offset), this.pos.y + random(-this.offset, this.offset), this.r);
		this.grad.addColorStop(0.2, this.color1);
		this.grad.addColorStop(random(0.85,1), this.color2);
		drawingContext.strokeStyle = this.grad;
		//line
		line(this.pos.x, this.pos.y- random(-this.r, 0), this.pos.x, this.pos.y + random(-this.r, 0));
	};

	this.explode = function() {
		this.particles2.push(new Particle2(this.pos.x, this.pos.y));
		for (let i = this.particles2.length - 1; i > 0; i--) {
			this.particles2[i].r = this.r / 10;
			if (this.r < 5) {
				this.r += 0.0025;
			}
			this.particles2[i].color1 = this.color1;
			this.particles2[i].color2 = this.color2;
			this.particles2[i].alpha1 = this.alpha1;
			this.particles2[i].alpha2 = this.alpha2;
			this.particles2[i].show();
			this.particles2[i].update();

			if (this.particles2[i].finished()) {
				this.particles2.splice(i, 1);
			}
		}
	};

	this.finished = function() {
		return this.alpha2 < 10;
	};
}

// === Tab: semi-Particle ===
function Particle2(x, y) {
	this.x = x;
	this.y = y;
	this.explode = new Particle(this.x, this.y);
	this.pos = createVector(this.x, this.y);
	this.vel = createVector(random(-0.25, 0.25),0);
	this.acc = createVector(-random(-0.025, 0.025), 0*random(-0.025, 0.025));
	this.alpha1 = 0;
	this.alpha2 = 0;
	this.r = 1;
	this.color1 = 0;
	this.color2 = 0;
	this.grad = 0;
	this.offset = 0.5;

	this.update = function() {
		this.vel.add(this.acc);
		this.pos.add(this.vel);
		this.alpha1 += random(0.5,1);
		this.alpha2 -= random(1);
	}

	this.show = function() {
		// noStroke();
		// fill(0);
		noFill();
		strokeWeight(random());
		this.grad = drawingContext.createRadialGradient(this.pos.x + random(-this.offset,this.offset), this.pos.y + random(-this.offset,this.offset), 0, 
																										this.pos.x + random(-this.offset,this.offset), this.pos.y + random(-this.offset,this.offset), this.r);
		this.grad.addColorStop(0.5, this.color1);
		this.grad.addColorStop(0.95, this.color2);
		drawingContext.fillStyle = this.grad;
		line(this.pos.x, this.pos.y- random(-this.r, 0), this.pos.x + random(0, this.offset), this.pos.y + random(-this.offset, 0));
	}

	this.finished = function() {
		return this.alpha2 < 2;
	};
}

